const j = $json;

const text = (v) => String(v ?? '').trim();

const extractEmail = (value) => {
  const raw = text(value);
  const match =
    raw.match(/<\s*([^<>\s]+@[^<>\s]+)\s*>/) ||
    raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return String(match?.[1] || '').trim().toLowerCase();
};

const fromRaw = text(j.From || j.from || j.sender);
const emailCliente = extractEmail(fromRaw);

if (!emailCliente) {
  throw new Error(`No se pudo extraer el remitente desde From="${fromRaw}"`);
}

const asuntoOriginal = text(j.Subject || j.subject || 'Sin asunto');
const mensaje = text(j.textPlain || j.text || j.body || j.snippet || 'El correo no contiene texto visible.')
  .replace(/\u0000/g, '')
  .slice(0, 12000);

// En esta versión estable respondemos desde ventas.
// Luego podremos separar soporte/contacto con etiquetas de Gmail.
const replyFrom = 'ventas@transtech.com.py';

const propio =
  emailCliente === 'transtecheos@gmail.com' ||
  emailCliente.endsWith('@transtech.com.py');

const automatico =
  /(mailer-daemon|postmaster|no-?reply|do-?not-?reply)/i.test(fromRaw);

if (propio || automatico) {
  return [];
}

return [{
  json: {
    gmail_message_id: j.id || '',
    gmail_thread_id: j.threadId || '',
    remitente_original: fromRaw,
    email_cliente: emailCliente,
    canal: 'ventas',
    reply_from: replyFrom,
    asunto_original: asuntoOriginal,
    asunto_respuesta: /^re:/i.test(asuntoOriginal) ? asuntoOriginal : `Re: ${asuntoOriginal}`,
    mensaje
  }
}];

