let html =
  j.output?.[0]?.content?.[0]?.text ??
  j.output_text ??
  j.text ??
  j.response ??
  '';

html = String(html || '')
  .replace(/^```(?:html)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

if (!html) {
  html = '<p>Gracias por comunicarte con TransTech.</p><p>Recibimos tu mensaje y nuestro equipo lo revisará a la brevedad.</p><p>Saludos cordiales,</p><p><strong>Equipo TransTech</strong><br><a href="https://transtech.com.py">transtech.com.py</a></p>';
}

const to = String(j.email_cliente || '').trim().toLowerCase();

if (!to || !to.includes('@')) {
  throw new Error(`El Merge no entregó email_cliente. Campos recibidos: ${Object.keys(j).join(', ')}`);
}

return [{
  json: {
    to,
    from: j.reply_from || 'ventas@transtech.com.py',
    subject: j.asunto_respuesta || `Re: ${j.asunto_original || 'Consulta'}`,
    html,
    canal: j.canal || 'ventas',
    gmail_message_id: j.gmail_message_id || '',
    gmail_thread_id: j.gmail_thread_id || ''
  }
}];

